                                ORDER BY t.n
                            LOOP
                                INSERT INTO "ExhaustiveSearchInstanceTrialInstanceVariable" ("ExhaustiveSearchInstanceVariableId", "Removed",
                                    "ExhaustiveSearchInstanceTrialInstanceId", "VariableSequence")
                                VALUES (pg_temp.seed_exhaustive_new('ExhaustiveSearchInstanceVariable', (v_e->>1)::integer), (v_e->>2)::smallint,
                                    pg_temp.seed_exhaustive_new('ExhaustiveSearchInstanceTrialInstance', (v_e->>3)::integer), (v_e->>4)::integer)
                                RETURNING "Id" INTO v_new;

                                INSERT INTO pg_temp.seed_exhaustive_map ("Name", "Old", "New") VALUES ('ExhaustiveSearchInstanceTrialInstanceVariable', (v_e->>0)::integer, v_new);
                            END LOOP;

                            INSERT INTO "ExhaustiveSearchInstancePromotedTrialInstanceSensitivity" ("Sensitivity", "ExhaustiveSearchInstanceTrialInstanceVariableId",
                                "SensitivityRank")
                            SELECT (t.e->>1)::double precision, pg_temp.seed_exhaustive_new('ExhaustiveSearchInstanceTrialInstanceVariable', (t.e->>2)::integer),
                                (t.e->>3)::integer
                            FROM jsonb_array_elements(pg_temp.seed_exhaustive_rows('ExhaustiveSearchInstancePromotedTrialInstanceSensitivity')) WITH ORDINALITY AS t(e, n)
                            ORDER BY t.n;

                            FOR v_e IN
                                SELECT t.e FROM jsonb_array_elements(pg_temp.seed_exhaustive_rows('ExhaustiveSearchInstancePromotedTrialInstanceVariable')) WITH ORDINALITY AS t(e, n)
                                ORDER BY t.n
                            LOOP
                                INSERT INTO "ExhaustiveSearchInstancePromotedTrialInstanceVariable" ("ExhaustiveSearchInstanceTrialInstanceVariableId", "Mean",
                                    "StandardDeviation", "Maximum", "Minimum", "Iqr", "Positive")
                                VALUES (pg_temp.seed_exhaustive_new('ExhaustiveSearchInstanceTrialInstanceVariable', (v_e->>1)::integer), (v_e->>2)::double precision,
                                    (v_e->>3)::double precision, (v_e->>4)::double precision, (v_e->>5)::double precision, (v_e->>6)::double precision, (v_e->>7)::boolean)
                                RETURNING "Id" INTO v_new;

                                INSERT INTO pg_temp.seed_exhaustive_map ("Name", "Old", "New") VALUES ('ExhaustiveSearchInstancePromotedTrialInstanceVariable', (v_e->>0)::integer, v_new);
                            END LOOP;

                            INSERT INTO "ExhaustiveSearchInstancePrescriptionHistogram" ("ExhaustiveSearchInstancePromotedTrialInstanceVariableId", "BinIndex",
                                "BinRangeStart", "BinRangeEnd", "Frequency")
                            SELECT pg_temp.seed_exhaustive_new('ExhaustiveSearchInstancePromotedTrialInstanceVariable', (t.e->>1)::integer), (t.e->>2)::integer,
                                (t.e->>3)::double precision, (t.e->>4)::double precision, (t.e->>5)::integer
                            FROM jsonb_array_elements(pg_temp.seed_exhaustive_rows('ExhaustiveSearchInstancePrescriptionHistogram')) WITH ORDINALITY AS t(e, n)
                            ORDER BY t.n;

                            FOR v_e IN
                                SELECT t.e FROM jsonb_array_elements(pg_temp.seed_exhaustive_rows('ExhaustiveSearchInstanceVariableClassification')) WITH ORDINALITY AS t(e, n)
                                ORDER BY t.n
                            LOOP
                                INSERT INTO "ExhaustiveSearchInstanceVariableClassification" ("ExhaustiveSearchInstanceVariableId", "Mode", "Mean", "StandardDeviation",
                                    "Kurtosis", "Skewness", "Maximum", "Minimum", "Iqr", "DistinctValues", "Bins")
                                VALUES (pg_temp.seed_exhaustive_new('ExhaustiveSearchInstanceVariable', (v_e->>1)::integer), (v_e->>2)::double precision,
                                    (v_e->>3)::double precision, (v_e->>4)::double precision, (v_e->>5)::double precision, (v_e->>6)::double precision,
                                    (v_e->>7)::double precision, (v_e->>8)::double precision, (v_e->>9)::double precision, (v_e->>10)::integer, (v_e->>11)::integer)
                                RETURNING "Id" INTO v_new;

                                INSERT INTO pg_temp.seed_exhaustive_map ("Name", "Old", "New") VALUES ('ExhaustiveSearchInstanceVariableClassification', (v_e->>0)::integer, v_new);
                            END LOOP;

                            INSERT INTO "ExhaustiveSearchInstanceVariableHistogram" ("ExhaustiveSearchInstanceVariableId", "BinSequence", "BinRangeStart", "BinRangeEnd",
                                "Frequency")
                            SELECT pg_temp.seed_exhaustive_new('ExhaustiveSearchInstanceVariable', (t.e->>1)::integer), (t.e->>2)::integer, (t.e->>3)::double precision,
                                (t.e->>4)::double precision, (t.e->>5)::integer
                            FROM jsonb_array_elements(pg_temp.seed_exhaustive_rows('ExhaustiveSearchInstanceVariableHistogram')) WITH ORDINALITY AS t(e, n)
                            ORDER BY t.n;

                            INSERT INTO "ExhaustiveSearchInstanceVariableHistogramClass" ("ExhaustiveSearchInstanceVariableId", "ClassLabel", "BinSequence",
                                "BinRangeStart", "BinRangeEnd", "Frequency")
                            SELECT pg_temp.seed_exhaustive_new('ExhaustiveSearchInstanceVariable', (t.e->>1)::integer), (t.e->>2)::integer, (t.e->>3)::integer,
                                (t.e->>4)::double precision, (t.e->>5)::double precision, (t.e->>6)::integer
                            FROM jsonb_array_elements(pg_temp.seed_exhaustive_rows('ExhaustiveSearchInstanceVariableHistogramClass')) WITH ORDINALITY AS t(e, n)
                            ORDER BY t.n;

                            INSERT INTO "ExhaustiveSearchInstanceVariableHistogramClassification" ("ExhaustiveSearchInstanceVariableClassificationId", "BinSequence",
                                "BinRangeStart", "BinRangeEnd", "Frequency")
                            SELECT pg_temp.seed_exhaustive_new('ExhaustiveSearchInstanceVariableClassification', (t.e->>1)::integer), (t.e->>2)::integer,
                                (t.e->>3)::double precision, (t.e->>4)::double precision, (t.e->>5)::integer
                            FROM jsonb_array_elements(pg_temp.seed_exhaustive_rows('ExhaustiveSearchInstanceVariableHistogramClassification')) WITH ORDINALITY AS t(e, n)
                            ORDER BY t.n;

                            INSERT INTO "ExhaustiveSearchInstanceVariableMultiCollinearity" ("ExhaustiveSearchInstanceVariableId",
                                "TestExhaustiveSearchInstanceVariableId", "Correlation", "CorrelationAbsRank")
                            SELECT pg_temp.seed_exhaustive_new('ExhaustiveSearchInstanceVariable', (t.e->>1)::integer),
                                pg_temp.seed_exhaustive_new('ExhaustiveSearchInstanceVariable', (t.e->>2)::integer), (t.e->>3)::double precision, (t.e->>4)::integer
                            FROM jsonb_array_elements(pg_temp.seed_exhaustive_rows('ExhaustiveSearchInstanceVariableMultiCollinearity')) WITH ORDINALITY AS t(e, n)
                            ORDER BY t.n;

                            INSERT INTO "EntityApproval" ("TenantRegistryId", "EntityApprovalKindId", "EntityId", "EntityVersion", "StateId", "CreatedDate",
                                "CreatedUser", "Guid")
                            SELECT v_tenant, (t.e->>1)::integer, pg_temp.seed_exhaustive_new('ExhaustiveSearchInstance', (t.e->>2)::integer), (t.e->>3)::integer,
                                (t.e->>4)::integer, (t.e->>5)::timestamp + v_shift, t.e->>6, gen_random_uuid()
                            FROM jsonb_array_elements(pg_temp.seed_exhaustive_rows('EntityApproval')) WITH ORDINALITY AS t(e, n)
                            ORDER BY t.n;

                            INSERT INTO "ExhaustiveSearchInstancePromotedTrialInstancePredictedActualVar" (
                                "ExhaustiveSearchInstancePromotedTrialInstancePredictedActualId", "ExhaustiveSearchInstanceVariableId", "Value")
                            SELECT pg_temp.seed_exhaustive_new('ExhaustiveSearchInstancePromotedTrialInstancePredictedActual', (r.e->>0)::integer),
                                   pg_temp.seed_exhaustive_new('ExhaustiveSearchInstanceVariable', (g.e->1->>(c.n - 2)::integer)::integer),
                                   c.x::double precision
                            FROM jsonb_array_elements(pg_temp.seed_exhaustive_rows('ExhaustiveSearchInstancePromotedTrialInstancePredictedActualVar')) WITH ORDINALITY AS g(e, n)
                            CROSS JOIN LATERAL jsonb_array_elements(g.e->2) WITH ORDINALITY AS r(e, n)
                            CROSS JOIN LATERAL jsonb_array_elements_text(r.e) WITH ORDINALITY AS c(x, n)
                            WHERE c.n > 1
                            ORDER BY g.n, r.n, c.n;
                        END
                        $seed$;
                        """);
        }

        private void DropStage()
        {
            Execute.Sql("""
                        DROP FUNCTION IF EXISTS pg_temp.seed_exhaustive_new(text, integer);
                        DROP FUNCTION IF EXISTS pg_temp.seed_exhaustive_rows(text);
                        DROP TABLE IF EXISTS pg_temp.seed_exhaustive_map;
                        DROP TABLE IF EXISTS pg_temp.seed_exhaustive_stage;
                        """);
        }
    }
}